sp_CriarContaPagar	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarContaPagar`(\n\n    IN p_idEmpresa     INT,\n\n    IN p_fornecedor_id INT,\n\n    IN p_descricao     VARCHAR(300),\n\n    IN p_valorTotal    DECIMAL(10,2),\n\n    IN p_dthVencimento DATE\n\n)\nBEGIN\n\n    INSERT INTO ContaPagar (idEmpresa, fornecedor_id, descricao, valorTotal, dthVencimento, status)\n\n    VALUES (p_idEmpresa, p_fornecedor_id, p_descricao, p_valorTotal, p_dthVencimento, 'ABERTO');\n\n    SELECT LAST_INSERT_ID() AS idContaPagar;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
